import{_ as r,l,o as e,c as n,v as o,p as s,x as t,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"齐次生产与欧拉定理","description":"","frontmatter":{"title":"齐次生产与欧拉定理","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/homothetic-production.md","filePath":"econ/homothetic-production.md","lastUpdated":1789023840000}'),c={name:"econ/homothetic-production.md"};function E(m,a,_,A,f,u){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="齐次生产与欧拉定理" tabindex="-1">齐次生产与欧拉定理 <a class="header-anchor" href="#齐次生产与欧拉定理" aria-label="Permalink to &quot;齐次生产与欧拉定理&quot;">​</a></h1><div class="epigraph"><p>一次齐次的技术上，产出恰好等于边际产出乘要素的加总——竞争支付把产品分尽，不剩一笔「纯利润」。</p><footer>—— 据 Varian, Microeconomic Analysis；Euler 齐次函数定理整理</footer></div><p><a href="/econ/free-disposal-inada">上一课</a>用自由处置与 Inada 把分析钉在有效内点。本课不重写边际在原点炸掉，也不把 \\(Y\\) 的闭与可歇业再列一遍。缺口是：<a href="/econ/production-technology">技术课</a>边注里提过一次齐次与欧拉分尽，后课成本、竞争零利润要把它从边注升级成定理：何时要素的边际贡献把 \\(q\\) 加尽，何时留下残差。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(f\\) 齐次 \\(k\\) 次指 \\(f(\\lambda z)=\\lambda^k f(z)\\) 对一切 \\(\\lambda\\gt 0\\)。\\(k=1\\) 即 CRS 在单产出语言里的写法。可微时欧拉定理给出</p> \\[\\sum_j z_j\\frac{\\partial f}{\\partial z_j}(z)=k\\,f(z). \\]<p>缺口是读 \\(k=1\\)：若要素按边际产出付酬 \\(w_j=p\\,\\mathrm{MP}_j\\)（价格接受，后课才正式做），则 \\(\\sum w_j z_j=p q\\)，会计上的增加值被要素分尽。\\(k\\lt 1\\)（DRS）则 \\(\\sum w_j z_j\\lt p q\\)，留下正利润；\\(k\\gt 1\\) 则支付超过产值，竞争支付站不住——与技术课 IRS 炸开供给是同一道墙。</p><p>位似（homothetic）更弱：等产量是彼此的径向放大，\\(f=F(h(z))\\)，\\(h\\) 一次齐次，\\(F\\) 递增。成本份额沿射线不变，但欧拉分尽仍要求底层 \\(h\\) 一次齐次且竞争按 \\(h\\) 的边际付酬。不要把位似直接叫 CRS。</p><h3 id="分尽是几何-不是分配正义" tabindex="-1">分尽是几何，不是分配正义 <a class="header-anchor" href="#分尽是几何-不是分配正义" aria-label="Permalink to &quot;分尽是几何，不是分配正义&quot;">​</a></h3><p>欧拉等式是齐次函数的恒等式，不论证「劳动应得多少」。它只说：若技术是一次齐次且按边际产品付酬，账加得上。规模弹性不是 \\(k\\) 时，残差必须有承担者（利润、固定要素）。上一课的 Inada 保证内点，使偏导数存在；本课不管轴上的极限，只管射线。</p><p><span class="marginnote">欧拉分尽与 \\(0\\in Y\\)、自由处置一起，才让 CRS 下竞争利润只能是零：放大可行计划不改变单位产值，正利润会被复制到无穷。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先检验齐次：沿射线 \\(z\\mapsto\\lambda z\\) 看产出是否按 \\(\\lambda^k\\) 走。Cobb–Douglas 指数和为 \\(k\\)；CES 常写成一次齐次。再写欧拉，不必把欧拉定理从微积分再证一遍——本课用它。成本最小化下一课会看到：一次齐次则 \\(c(w,q)=q\\,c(w,1)\\)，平均成本不随 \\(q\\) 变。那是本课几何的对偶面，本课只钉原空间。</p><p>位似技术的 TRS 沿射线不变，替代弹性可以单独规定。齐次次数管规模，位似管等产量形状，两刀正交——与技术课「规模报酬与替代正交」对齐，本课给出函数语言。</p>',14)),(e(),s(h,null,{default:t(()=>[d(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9A%E6%9C%89%E6%95%88%E5%86%85%E7%82%B9%22%5D%20--%3E%20HOM%5B%22f%20%E9%BD%90%E6%AC%A1%20k%20%E6%AC%A1%22%5D%0A%20%20HOM%20--%3E%20EU%5B%22%E6%AC%A7%E6%8B%89%EF%BC%9Az%C2%B7%E2%88%87f%20%3D%20k%20f%22%5D%0A%20%20EU%20--%3E%20CRS%5B%22k%3D1%EF%BC%9A%E8%A6%81%E7%B4%A0%E6%94%AF%E4%BB%98%E5%88%86%E5%B0%BD%20q%22%5D%0A%20%20EU%20--%3E%20DRS%5B%22k%EF%BC%9C1%EF%BC%9A%E7%95%99%E4%B8%8B%E5%88%A9%E6%B6%A6%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20CRS%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%88%90%E6%9C%AC%E5%AF%B9%20q%20%E7%BA%BF%E6%80%A7%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>本课仍不把 \\(w\\)、\\(p\\) 当选择。分尽等式里出现的 \\(w=p\\,\\mathrm{MP}\\) 是对照，不是本课的厂商问题。也不把残差写成限价簿上的做市利润。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么一次齐次会分尽：把所有投入同时放大一丁点，产出按同一比例涨；这笔涨正好等于各边际产出乘原投入的和。竞争把边际产出标成要素价格，加总就等于产值。\\(k\\ne 1\\) 时，按比例放大的产出增量与「沿各轴分别算边际再加总」差一个因子，残差出现。</p><p>位似的机制是等产量自相似：要素价格比钉住 TRS 之后，最优投入比例与 \\(q\\) 无关，扩张路径是射线。这为下一课条件需求的齐次性做铺垫，但条件需求本身还没有价格。</p><p><span class="marginnote">不要把生产函数的齐次与<a href="/econ/quasilinear-homothetic">位似偏好</a>焊死成「厂商也有位似效用」。\\(f\\) 是可行性；支出份额不变是几何推论，不是排序。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>局部齐次（只在某锥上）时，欧拉只在该锥上成立。不可微时改用欧拉的支撑形式，分尽变成「存在一组支撑价格使等式成立」。整数投入破坏任意 \\(\\lambda\\)。</p><p>联合生产没有单一 \\(f\\)，要回到 \\(Y\\) 的锥：CRS 即 \\(Y\\) 是锥，竞争利润在无固定成本时为零或无穷。本课单产出写法是特例。也不把欧拉分尽写成宏观核算恒等式的证明——核算是定义，这里是技术前提。</p><p>后课默认：一次齐次则欧拉分尽产出；成本将随 \\(q\\) 线性齐变。位似只保证扩张路径为射线。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>齐次 \\(k\\) 次加可微，欧拉把 \\(\\sum z_j\\mathrm{MP}_j\\) 钉成 \\(k f\\)。</li><li>\\(k=1\\) 时竞争边际支付分尽产值；\\(k\\ne 1\\) 必有残差。</li><li>位似管等产量自相似，不等于 CRS。</li><li>下一课贴上要素价格，做成本最小化。</li><li>出处：Varian, <em>Microeconomic Analysis</em>；齐次函数的欧拉定理；对照 Mas-Colell, Whinston and Green 第 5 章。</li></ul>',11))])}const C=r(c,[["render",E]]);export{k as __pageData,C as default};
